from solution import fib
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref_fib(n: int) -> int:
    """Obviously correct iterative reference: F0=0, F1=1."""
    assert isinstance(n, int) and n >= 0
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


# --- explicit examples from spec docstring ---
def test_example_fib_10_is_55():
    assert fib(10) == 55


def test_example_fib_1_is_1():
    assert fib(1) == 1


def test_example_fib_8_is_21():
    assert fib(8) == 21


# --- boundary implied by "n-th Fibonacci number" ---
def test_zero_base_case_is_zero():
    # Standard Fibonacci: F0 == 0. Spec examples (F10==55, F8==21)
    # pin 0-indexed convention, so F0 must be 0.
    assert fib(0) == 0


def test_fib_2_is_1():
    assert fib(2) == 1


def test_fib_3_is_2():
    assert fib(3) == 2


def test_fib_0_1_2_seed_sequence():
    assert (fib(0), fib(1), fib(2)) == (0, 1, 1)


# --- equivalence to reference model ---
@given(st.integers(min_value=0, max_value=15))
def test_equivalence_to_iterative_reference(n):
    assert fib(n) == ref_fib(n)


@given(st.integers(min_value=0, max_value=12))
def test_recurrence_relation_holds(n):
    # F(n+2) == F(n+1) + F(n) for all n >= 0
    assert fib(n + 2) == fib(n + 1) + fib(n)


def test_recurrence_at_lowest_boundary():
    # F2 == F1 + F0
    assert fib(2) == fib(1) + fib(0)


@given(st.integers(min_value=2, max_value=15))
def test_monotonic_non_decreasing_from_2(n):
    assert fib(n + 1) >= fib(n)


@given(st.integers(min_value=0, max_value=15))
def test_fib_nonnegative(n):
    assert fib(n) >= 0


@given(st.integers(min_value=0, max_value=14))
def test_sum_identity(n):
    # sum_{i=0}^{n} F(i) == F(n+2) - 1
    assert sum(fib(i) for i in range(n + 1)) == fib(n + 2) - 1


@given(st.integers(min_value=0, max_value=12))
def test_parity_period_matches_reference(n):
    # Fibonacci parity is periodic (odd, odd, even); check implementation matches.
    assert (fib(n) % 2) == (ref_fib(n) % 2)


def test_negative_input_raises_value_error():
    with pytest.raises(ValueError):
        fib(-1)


@given(st.integers(min_value=-10, max_value=-1))
def test_negative_inputs_raise_value_error(n):
    with pytest.raises(ValueError):
        fib(n)
